def best_circular_selection(values, k):
    n = len(values)
    if k == 0:
        return 0

    max_k = 1 if n == 1 else n // 2
    if k < 0 or k > max_k:
        raise ValueError(f"Cannot select {k} non-adjacent elements from {n} circular elements.")

    if k == 1:
        return max(values)

    neg_inf = -10**18

    def solve_linear(arr, target_k):
        if target_k == 0:
            return 0
        dp2 = [0] + [neg_inf] * target_k
        dp1 = [0] + [neg_inf] * target_k
        dp0 = [0] + [neg_inf] * target_k

        for i, x in enumerate(arr):
            limit = (i + 2) // 2
            if limit > target_k:
                limit = target_k
            for j in range(1, limit + 1):
                cand = dp2[j - 1] + x
                prev = dp1[j]
                dp0[j] = cand if cand > prev else prev
            dp2, dp1, dp0 = dp1, dp0, dp2

        return dp1[target_k]

    best_without_0 = solve_linear(values[1:], k)
    best_with_0 = values[0] + solve_linear(values[2:-1], k - 1)
    return best_without_0 if best_without_0 > best_with_0 else best_with_0

from collections import deque


def min_steps(grid, c):
    R = len(grid)
    C = len(grid[0])

    if grid[0][0] == -1 or grid[R - 1][C - 1] == -1:
        return -1
    if R == 1 and C == 1:
        return 0

    # Pad grid with a -1 border to avoid bounds checks inside BFS
    W = C + 2
    H = R + 2
    flat = [-1] * (H * W)
    for r in range(R):
        row = grid[r]
        base = (r + 1) * W + 1
        flat[base : base + C] = row

    start = W + 1
    end = R * W + C

    def bfs(src):
        dist = [-1] * (H * W)
        dist[src] = 0
        q = deque([src])
        dirs = (-W, W, -1, 1)
        while q:
            u = q.popleft()
            nd = dist[u] + 1
            for d in dirs:
                v = u + d
                if flat[v] >= 0 and dist[v] == -1:
                    dist[v] = nd
                    q.append(v)
        return dist

    d1 = bfs(start)
    d2 = bfs(end)

    min_d1 = {}
    min_d2 = {}
    for i in range(start, end + 1):
        lbl = flat[i]
        if lbl >= 0:
            v1 = d1[i]
            if v1 != -1:
                prev = min_d1.get(lbl)
                if prev is None or v1 < prev:
                    min_d1[lbl] = v1
            v2 = d2[i]
            if v2 != -1:
                prev = min_d2.get(lbl)
                if prev is None or v2 < prev:
                    min_d2[lbl] = v2

    ans = d1[end]
    for lbl, v1 in min_d1.items():
        v2 = min_d2.get(lbl)
        if v2 is not None:
            cand = v1 + c + v2
            if ans == -1 or cand < ans:
                ans = cand

    return ans

def smallest_balanced(s: str) -> str:
    n = len(s)
    if n % 2 != 0:
        raise ValueError("String length must be even to be balanced.")

    half = n // 2
    fixed_open = s.count("(")
    fixed_close = s.count(")")
    if fixed_open > half or fixed_close > half:
        raise ValueError("Too many fixed parentheses to balance.")

    need_open = half - fixed_open
    bal = 0
    out = []

    for ch in s:
        if ch == "(":
            bal += 1
            out.append("(")
        elif ch == ")":
            bal -= 1
            out.append(")")
        else:  # ch == '?'
            if need_open > 0:
                need_open -= 1
                bal += 1
                out.append("(")
            else:
                bal -= 1
                out.append(")")

        if bal < 0:
            raise ValueError("No valid balanced replacement exists.")

    return "".join(out)

def longest_spaced_repeat(s: str, gap: int) -> int:
    n = len(s)
    best = 0
    for d in range(gap + 1, n):
        limit = d - gap
        # Neither the gap constraint nor the remaining string length can beat `best`
        if limit <= best or n - d <= best:
            continue
        cur = 0
        for p in range(n - 1 - d, -1, -1):
            if s[p] == s[p + d]:
                cur += 1
                if cur > best:
                    if cur >= limit:
                        best = limit
                        break
                    best = cur
            else:
                cur = 0
    return best

def min_insertions(s, allowed):
    n = len(s)
    if n <= 1:
        return 0

    allowed_set = set(allowed)
    inf = n + 1
    dp = [[0] * n for _ in range(n)]

    for i in range(n - 2, -1, -1):
        si = s[i]
        si_allowed = si in allowed_set
        dp_i = dp[i]
        dp_next = dp[i + 1]

        for j in range(i + 1, n):
            if si == s[j]:
                dp_i[j] = dp_next[j - 1]
            else:
                best = inf
                if si_allowed:
                    best = 1 + dp_next[j]
                if s[j] in allowed_set:
                    cand = 1 + dp_i[j - 1]
                    if cand < best:
                        best = cand
                dp_i[j] = best

    ans = dp[0][n - 1]
    return ans if ans < inf else -1

def resolve_build_order(deps):
    graph = {}
    for pkg, ds in deps.items():
        graph.setdefault(pkg, set())
        for d in ds:
            graph.setdefault(d, set())
            graph[pkg].add(d)

    order = []
    visiting = set()
    visited = set()

    for start in sorted(graph):
        if start in visited:
            continue
        stack = [(start, False)]
        while stack:
            node, processed = stack.pop()
            if processed:
                visiting.remove(node)
                visited.add(node)
                order.append(node)
            elif node not in visited:
                if node in visiting:
                    raise ValueError("dependency cycle detected at " + node)
                visiting.add(node)
                stack.append((node, True))
                for dep in sorted(graph[node], reverse=True):
                    if dep not in visited:
                        if dep in visiting:
                            raise ValueError("dependency cycle detected at " + dep)
                        stack.append((dep, False))

    return order

import re

_AMOUNT_RE = re.compile(r"([0-9]+)(?:\.([0-9]{1,2}))?")


def compute_balances(transactions):
    balances = {}
    for tx in transactions:
        amount = tx["amount"]
        if not isinstance(amount, str):
            raise ValueError("amount must be a string")

        match = _AMOUNT_RE.fullmatch(amount)
        if not match:
            raise ValueError(f"invalid amount: {amount!r}")

        whole, frac = match.groups()
        cents = int(whole) * 100 + int((frac or "").ljust(2, "0"))
        if cents <= 0:
            raise ValueError("amount must be positive")

        balances[tx["from"]] = balances.get(tx["from"], 0) - cents
        balances[tx["to"]] = balances.get(tx["to"], 0) + cents
    return balances

import functools


def memoize(func):
    cache = {}

    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        key = (args, frozenset(kwargs.items()))
        if key in cache:
            wrapper.hits += 1
            return cache[key]
        wrapper.misses += 1
        result = func(*args, **kwargs)
        cache[key] = result
        return result

    wrapper.hits = 0
    wrapper.misses = 0
    return wrapper

def apply_hunks(lines, hunks):
    ordered = sorted(hunks, key=lambda h: h[0])
    for start, delete, _ in ordered:
        if start < 0 or delete < 0 or start + delete > len(lines):
            raise ValueError("hunk out of range")
    for i in range(1, len(ordered)):
        prev_start, prev_delete, _ = ordered[i - 1]
        curr_start = ordered[i][0]
        if curr_start == prev_start or curr_start < prev_start + prev_delete:
            raise ValueError("conflicting hunks")

    result = []
    pos = 0
    for start, delete, insert in ordered:
        result.extend(lines[pos:start])
        result.extend(insert)
        pos = start + delete
    result.extend(lines[pos:])
    return result

