class CountingBag:
    """A multiset of hashable items tracking counts and entry-order tie-breaking."""

    def __init__(self) -> None:
        # Python 3.7+ dicts preserve insertion order. Removing an item when its
        # count hits 0 and re-inserting it later naturally assigns a new entry
        # position at the end, while in-place count increments preserve the
        # original entry position.
        self._counts: dict[Hashable, int] = {}
        self._total: int = 0

    def add(self, item: Hashable) -> int:
        """Add one occurrence of item and return its new count."""
        new_count = self._counts.get(item, 0) + 1
        self._counts[item] = new_count
        self._total += 1
        return new_count

    def discard(self, item: Hashable) -> bool:
        """Remove one occurrence of item; return True if removed, False if absent."""
        current = self._counts.get(item, 0)
        if current == 0:
            return False
        if current == 1:
            del self._counts[item]
        else:
            self._counts[item] = current - 1
        self._total -= 1
        return True

    def count(self, item: Hashable) -> int:
        """Return the current count of item (0 if absent)."""
        return self._counts.get(item, 0)

    def __len__(self) -> int:
        """Return the total number of occurrences across all items."""
        return self._total

    def distinct(self) -> int:
        """Return the number of distinct items currently present."""
        return len(self._counts)

    def most_common(self, k: int) -> List[Tuple[Hashable, int]]:
        """Return up to k (item, count) tuples ordered by count descending,
        breaking ties by earlier entry moment first.
        """
        if k < 0:
            raise ValueError("k must be non-negative")
        if k == 0 or not self._counts:
            return []
        if k >= len(self._counts):
            # Timsort is stable even with reverse=True, preserving dict entry order on ties.
            return sorted(self._counts.items(), key=lambda kv: kv[1], reverse=True)
        # Include enumeration index so ties break deterministically without comparing items.
        return [
            (item, cnt)
            for _, _, item, cnt in heapq.nsmallest(
                k,
                ((-cnt, idx, item, cnt) for idx, (item, cnt) in enumerate(self._counts.items())),
            )
        ]

