class TTLCache:
    """Fixed-capacity LRU cache with per-entry TTL driven by an explicit clock."""

    def __init__(self, capacity: int) -> None:
        if isinstance(capacity, bool) or not isinstance(capacity, int) or capacity < 1:
            raise ValueError("capacity must be an integer >= 1")
        self._capacity = capacity
        # key -> [value, expires_at, seq]
        self._entries: OrderedDict = OrderedDict()
        # min-heap of (expires_at, seq, key); seq breaks ties so keys needn't be comparable
        self._heap: list[tuple[float, int, object]] = []
        self._seq = 0

        self._hits = 0
        self._misses = 0
        self._evictions = 0
        self._expirations = 0

    def _purge(self, now: float) -> None:
        while self._heap and self._heap[0][0] <= now:
            _, seq, key = heapq.heappop(self._heap)
            entry = self._entries.get(key)
            if entry is not None and entry[2] == seq:
                del self._entries[key]
                self._expirations += 1

        if len(self._heap) > max(64, 2 * len(self._entries)):
            self._heap = [
                (entry[1], entry[2], k)
                for k, entry in self._entries.items()
                if entry[1] is not None
            ]
            heapq.heapify(self._heap)

    def put(self, key, value, now: float, ttl: float | None = None) -> None:
        if ttl is not None and (isinstance(ttl, bool) or ttl <= 0):
            raise ValueError("ttl must be None or a positive number")

        self._purge(now)

        expires_at = None if ttl is None else now + ttl
        seq = self._seq
        self._seq += 1

        if key in self._entries:
            self._entries[key] = [value, expires_at, seq]
            self._entries.move_to_end(key)
        else:
            if len(self._entries) >= self._capacity:
                self._entries.popitem(last=False)
                self._evictions += 1
            self._entries[key] = [value, expires_at, seq]

        if expires_at is not None:
            heapq.heappush(self._heap, (expires_at, seq, key))

    def get(self, key, now: float):
        self._purge(now)

        entry = self._entries.get(key)
        if entry is None:
            self._misses += 1
            return None

        self._hits += 1
        self._entries.move_to_end(key)
        return entry[0]

    def stats(self) -> dict[str, int]:
        return {
            "hits": self._hits,
            "misses": self._misses,
            "evictions": self._evictions,
            "expirations": self._expirations,
        }

    def __len__(self) -> int:
        return len(self._entries)

from bisect import bisect_left, insort


class Leaderboard:
    _LOAD = 512

    def __init__(self) -> None:
        self._players: dict[object, tuple[int, int]] = {}
        self._lists: list[list[tuple[int, int, object]]] = []
        self._maxes: list[tuple[int, int]] = []
        self._seq = 0

    def _insert(self, item: tuple[int, int, object]) -> None:
        key = item[:2]
        if not self._lists:
            self._lists.append([item])
            self._maxes.append(key)
            return

        pos = bisect_left(self._maxes, key)
        if pos == len(self._lists):
            pos -= 1
            self._lists[pos].append(item)
            self._maxes[pos] = key
        else:
            insort(self._lists[pos], item)

        if len(self._lists[pos]) > 2 * self._LOAD:
            bucket = self._lists[pos]
            left = bucket[: self._LOAD]
            right = bucket[self._LOAD :]
            self._lists[pos] = left
            self._lists.insert(pos + 1, right)
            self._maxes[pos] = left[-1][:2]
            self._maxes.insert(pos + 1, right[-1][:2])

    def _remove(self, key: tuple[int, int]) -> None:
        pos = bisect_left(self._maxes, key)
        bucket = self._lists[pos]
        idx = bisect_left(bucket, key)
        del bucket[idx]
        if not bucket:
            del self._lists[pos]
            del self._maxes[pos]
        else:
            self._maxes[pos] = bucket[-1][:2]

    def submit(self, player: object, score: int) -> bool:
        existing = self._players.get(player)
        if existing is not None:
            best_score, old_seq = existing
            if score <= best_score:
                return False
            self._remove((-best_score, old_seq))

        seq = self._seq
        self._seq += 1
        self._players[player] = (score, seq)
        self._insert((-score, seq, player))
        return True

    def best(self, player: object) -> int:
        return self._players[player][0]

    def rank(self, player: object) -> int:
        best_score, _ = self._players[player]
        target = (-best_score, -1)
        pos = bisect_left(self._maxes, target)
        greater_count = sum(len(self._lists[i]) for i in range(pos))
        greater_count += bisect_left(self._lists[pos], target)
        return 1 + greater_count

    def top(self, k: int) -> list[tuple[object, int]]:
        if k < 0:
            raise ValueError("k must be non-negative")
        if k == 0:
            return []

        result: list[tuple[object, int]] = []
        for bucket in self._lists:
            for neg_score, _, player in bucket:
                result.append((player, -neg_score))
                if len(result) == k:
                    return result
        return result

    def player_count(self) -> int:
        return len(self._players)

from typing import Any


class UndoStack:
    """A LIFO stack whose mutating operations (push/pop) can be undone."""

    def __init__(self) -> None:
        self._items: list[Any] = []
        self._history: list[tuple[str, Any]] = []

    def push(self, x: Any) -> None:
        """Push x onto the top of the stack."""
        self._items.append(x)
        self._history.append(("push", None))

    def pop(self) -> Any:
        """Remove and return the top value. Raise IndexError if empty."""
        value = self._items.pop()
        self._history.append(("pop", value))
        return value

    def peek(self) -> Any:
        """Return the top value without removing it. Raise IndexError if empty."""
        return self._items[-1]

    def undo(self) -> None:
        """Reverse the most recent push or pop. Raise RuntimeError if none left."""
        if not self._history:
            raise RuntimeError("nothing to undo")
        op, value = self._history.pop()
        if op == "push":
            self._items.pop()
        else:
            self._items.append(value)

    def __len__(self) -> int:
        """Return the number of values currently on the stack."""
        return len(self._items)

