class VersionedKV:
    def __init__(self) -> None:
        self._snapshots: list[dict[Hashable, Any]] = [{}]
        self._working: dict[Hashable, Any] = self._snapshots[0]
        self._shared: bool = True

    def _ensure_writable(self) -> None:
        if self._shared:
            self._working = self._working.copy()
            self._shared = False

    def set(self, key: Hashable, value: Any) -> None:
        self._ensure_writable()
        self._working[key] = value

    def delete(self, key: Hashable) -> None:
        if key not in self._working:
            raise KeyError(key)
        self._ensure_writable()
        del self._working[key]

    def get(self, key: Hashable) -> Any:
        return self._working[key]

    def has(self, key: Hashable) -> bool:
        return key in self._working

    def commit(self) -> int:
        self._snapshots.append(self._working)
        self._shared = True
        return len(self._snapshots) - 1

    def get_at(self, key: Hashable, version: int) -> Any:
        if (
            isinstance(version, bool)
            or not isinstance(version, int)
            or not (1 <= version <= self.latest())
        ):
            raise ValueError(f"Invalid version: {version!r}")
        return self._snapshots[version][key]

    def rollback(self, version: int) -> None:
        if (
            isinstance(version, bool)
            or not isinstance(version, int)
            or not (0 <= version <= self.latest())
        ):
            raise ValueError(f"Invalid version: {version!r}")
        self._working = self._snapshots[version]
        self._shared = True

    def latest(self) -> int:
        return len(self._snapshots) - 1

import math


def rank_scores(scores: list) -> list[int]:
    if not scores:
        return []

    for score in scores:
        if math.isnan(score):
            raise ValueError("Scores cannot contain NaN.")

    sorted_scores = sorted(scores, reverse=True)
    rank_map = {}
    for index, score in enumerate(sorted_scores):
        if score not in rank_map:
            rank_map[score] = index + 1

    return [rank_map[score] for score in scores]

import unicodedata

_COMBINING_CATEGORIES = frozenset(("Mn", "Mc", "Me"))


def truncate_display(s: str, width: int) -> str:
    if width < 0:
        raise ValueError("width must be non-negative")
    if width == 0 or not s:
        return ""

    units = 0
    for i, ch in enumerate(s):
        is_mark = unicodedata.category(ch) in _COMBINING_CATEGORIES
        if not is_mark or units == 0:
            if units == width:
                return s[:i]
            units += 1

    return s

def kth_root_floor(n: int, k: int) -> int:
    if n < 0 or k < 1:
        raise ValueError("n must be >= 0 and k must be >= 1")
    if n < 2 or k == 1:
        return n
    if k >= n.bit_length():
        return 1

    # Initial upper bound x = 2 ** ceil(bit_length(n) / k) > n ** (1 / k)
    x = 1 << ((n.bit_length() + k - 1) // k)
    k_minus_1 = k - 1
    while True:
        y = (k_minus_1 * x + n // (x ** k_minus_1)) // k
        if y >= x:
            return x
        x = y

