def allocate_shares(total: int, weights: list) -> list[int]:
    if total < 0:
        raise ValueError("total must be >= 0")
    if not weights:
        raise ValueError("weights must be a non-empty list")

    frac_weights: list[Fraction] = []
    for w in weights:
        if isinstance(w, float) and not math.isfinite(w):
            raise ValueError("weights must be finite numbers")
        if w < 0:
            raise ValueError("weights must be >= 0")
        frac_weights.append(Fraction(w))

    total_weight = sum(frac_weights)
    if total_weight <= 0:
        raise ValueError("sum of weights must be > 0")

    shares: list[int] = []
    remainders: list[Fraction] = []

    for w in frac_weights:
        quota = total * w / total_weight
        floor_share = quota.numerator // quota.denominator
        shares.append(floor_share)
        remainders.append(quota - floor_share)

    remaining = total - sum(shares)
    order = sorted(range(len(weights)), key=lambda i: (-remainders[i], i))
    for i in order[:remaining]:
        shares[i] += 1

    return shares

