def weighted_median(values: list, weights: list) -> float:
    if len(values) != len(weights):
        raise ValueError("values and weights must have the same length")

    pairs = []
    for v, w in zip(values, weights):
        if not (w >= 0):
            raise ValueError("all weights must be non-negative")
        if w > 0:
            pairs.append((v, w))

    if not pairs:
        raise ValueError("dataset must be non-empty and have positive total weight")

    pairs.sort(key=lambda pair: pair[0])

    total_weight = math.fsum(w for _, w in pairs)
    threshold = total_weight / 2.0 - 1e-9

    cumulative = 0.0
    i = 0
    n = len(pairs)
    while i < n:
        v = pairs[i][0]
        while i < n and pairs[i][0] == v:
            cumulative += pairs[i][1]
            i += 1
        if cumulative >= threshold:
            return float(v)

    return float(pairs[-1][0])

import math


def vector_norm(v: list[float]) -> float:
    if not v:
        return 0.0

    scale = 0.0
    for x in v:
        if not math.isfinite(x):
            raise ValueError("vector entries must be finite (no NaN or infinity)")
        ax = abs(x)
        if ax > scale:
            scale = ax

    if scale == 0.0:
        return 0.0

    sum_sq = math.fsum((x / scale) ** 2 for x in v)
    return scale * math.sqrt(sum_sq)

