    heap_len = 0
    push = heappush
    replace = heapreplace

    for d, p in sorted(jobs):
        limit = d * cap
        if heap_len < limit:
            push(heap, p)
            heap_len += 1
        elif p > heap[0]:
            replace(heap, p)

    return sum(heap)

def recurring_counts(data: list[int], queries: list[tuple[int, int]]) -> list[int]:
    if not queries:
        return []

    n = len(data)
    ans = [0] * len(queries)
    if n < 2:
        return ans

    max_r = 0
    for l, r in queries:
        if l + 1 < r and r > max_r:
            max_r = r

    if max_r == 0:
        return ans

    by_r: list[list[int]] = [[] for _ in range(max_r + 1)]
    for qi, (l, r) in enumerate(queries):
        if l + 1 < r:
            by_r[r].append(qi)

    bit = [0] * (max_r + 1)
    prev = [-1] * max_r
    last: dict[int, int] = {}
    total = 0

    for i in range(max_r):
        x = data[i]
        p1 = last.get(x, -1)
        if p1 != -1:
            prev[i] = p1
            p2 = prev[p1]

            idx = p1 + 1
            while idx <= max_r:
                bit[idx] += 1
                idx += idx & -idx

            if p2 != -1:
                idx = p2 + 1
                while idx <= max_r:
                    bit[idx] -= 1
                    idx += idx & -idx
            else:
                total += 1

        last[x] = i

        q_list = by_r[i + 1]
        if q_list:
            for qi in q_list:
                idx = queries[qi][0]
                s = 0
                while idx:
                    s += bit[idx]
                    idx &= idx - 1
                ans[qi] = total - s

    return ans

from bisect import bisect_right


def count_dominant_pairs(seq: list[int]) -> int:
    n = len(seq)
    if n < 2:
        return 0

    vals = sorted(set(seq))
    m = len(vals)
    rank = {v: i for i, v in enumerate(vals, 1)}
    tree = [0] * (m + 1)

    ans = 0
    for j, x in enumerate(seq):
        idx = bisect_right(vals, 3 * x)
        if idx == 0:
            ans += j
        elif idx < m:
            s = 0
            k = idx
            while k:
                s += tree[k]
                k -= k & -k
            ans += j - s

        r = rank[x]
        while r <= m:
            tree[r] += 1
            r += r & -r

    return ans

def summarize_by_category(rows):
    if not isinstance(rows, list):
        raise TypeError("rows must be a list")

    summary = {}
    for i, row in enumerate(rows):
        if not isinstance(row, tuple) or len(row) != 3:
            raise TypeError(f"row {i} must be a 3-element tuple")

        category, amount, refunded = row

        if not isinstance(category, str) or category == "":
            raise ValueError(f"row {i} category must be a non-empty str")

        if isinstance(amount, bool) or not isinstance(amount, (int, float)):
            raise TypeError(f"row {i} amount must be an int or float")

        if not (amount >= 0):
            raise ValueError(f"row {i} amount must be >= 0")

        if not isinstance(refunded, bool):
            raise TypeError(f"row {i} refunded must be a bool")

        amt = float(amount)
        if category not in summary:
            summary[category] = {
                "count": 1,
                "gross": amt,
                "net": 0.0 if refunded else amt,
                "largest": amt,
            }
        else:
            entry = summary[category]
            entry["count"] += 1
            entry["gross"] += amt
            if not refunded:
                entry["net"] += amt
            if amt > entry["largest"]:
                entry["largest"] = amt

    return summary

def clamp_values(values, low, high):
    if not isinstance(values, list):
        raise TypeError("values must be a list")

    if (
        isinstance(low, bool)
        or not isinstance(low, (int, float))
        or isinstance(high, bool)
        or not isinstance(high, (int, float))
    ):
        raise TypeError("bounds must be numbers")

    if low > high:
        raise ValueError("low must not exceed high")

    result = []
    for i, item in enumerate(values):
        if isinstance(item, bool) or not isinstance(item, (int, float)):
            raise TypeError(f"invalid element at index {i}: expected int or float")

        if item < low:
            result.append(low)
        elif item > high:
            result.append(high)
        else:
            result.append(item)

    return result

def flatten_depth(nested, max_depth):
    if not isinstance(nested, list):
        raise TypeError("nested must be a list")
    if isinstance(max_depth, bool) or not isinstance(max_depth, int):
        raise TypeError("max_depth must be an int")
    if max_depth < 0:
        raise ValueError("max_depth must be >= 0")

    result = []
    stack = [(item, max_depth) for item in reversed(nested)]

    while stack:
        item, remaining_depth = stack.pop()
        if remaining_depth > 0 and isinstance(item, list):
            next_depth = remaining_depth - 1
            for sub_item in reversed(item):
                stack.append((sub_item, next_depth))
        else:
            result.append(item)

    return result

def parse_duration(text):
    if not isinstance(text, str):
        raise TypeError("expected str")
    if not text or text.isspace():
        raise ValueError("empty duration")

    units = ("h", "m", "s")
    multipliers = (3600, 60, 1)
    unit_idx = 0
    total = 0
    i = 0
    n = len(text)

    while i < n:
        if not ("0" <= text[i] <= "9"):
            raise ValueError("malformed duration")

        val = 0
        while i < n and "0" <= text[i] <= "9":
            val = val * 10 + (ord(text[i]) - 48)
            i += 1

        if i >= n:
            raise ValueError("malformed duration")

        ch = text[i]
        while unit_idx < 3 and units[unit_idx] != ch:
            unit_idx += 1
        if unit_idx >= 3:
            raise ValueError("malformed duration")

        total += val * multipliers[unit_idx]
        unit_idx += 1
        i += 1

    return total

def render_template(template, context):
    if not isinstance(template, str):
        raise TypeError("template must be a string")
    if not isinstance(context, dict):
        raise TypeError("context must be a dict")

    out = []
    n = len(template)
    i = 0

    while i < n:
        ch = template[i]
        if ch == "{":
            if i + 1 < n and template[i + 1] == "{":
                out.append("{")
                i += 2
            else:
                j = i + 1
                while j < n:
                    c = template[j]
                    if (
                        ("a" <= c <= "z")
                        or ("A" <= c <= "Z")
                        or ("0" <= c <= "9")
                        or c == "_"
                    ):
                        j += 1
                    else:
                        break
                if j == n:
                    raise ValueError("unclosed placeholder at position " + str(i))
                if template[j] != "}":
                    raise ValueError("invalid placeholder at position " + str(i))
                if j == i + 1:
                    raise ValueError("empty placeholder at position " + str(i))
                name = template[i + 1 : j]
                out.append(str(context[name]))
                i = j + 1
        elif ch == "}":
            if i + 1 < n and template[i + 1] == "}":
                out.append("}")
                i += 2
            else:
                raise ValueError("stray '}' at position " + str(i))
        else:
            start = i
            i += 1
            while i < n and template[i] != "{" and template[i] != "}":
                i += 1
            out.append(template[start:i])

    return "".join(out)

def eval_rpn(tokens):
    if not isinstance(tokens, list):
        raise TypeError("tokens must be a list")
    if not tokens:
        raise ValueError("empty expression")

    stack = []
    for i, tok in enumerate(tokens):
        if not isinstance(tok, str):
            raise TypeError(f"token {i} must be a str")

        if tok in ("+", "-", "*", "/"):
            if len(stack) < 2:
                raise ValueError(f"stack underflow at token {i}")
            right = stack.pop()
            left = stack.pop()
            if tok == "+":
                stack.append(left + right)
            elif tok == "-":
                stack.append(left - right)
            elif tok == "*":
                stack.append(left * right)
            else:
                if right == 0:
                    raise ZeroDivisionError(f"division by zero at token {i}")
                q = abs(left) // abs(right)
                stack.append(-q if (left < 0) != (right < 0) else q)
        else:
            digits = tok[1:] if tok and tok[0] in ("+", "-") else tok
            if not digits or not all("0" <= ch <= "9" for ch in digits):
                raise ValueError(f"unknown token at token {i}")
            stack.append(int(tok))

    if len(stack) > 1:
        raise ValueError("leftover operands")

    return stack[0]

def deep_get(data, path):
    if not isinstance(path, str):
        raise TypeError("path must be a string")
    if path == "":
        raise ValueError("path must not be empty")

    segments = path.split(".")
    if "" in segments:
        raise ValueError("path contains an empty segment")

    def _descend(node, idx):
        if idx == len(segments):
            return node

        seg = segments[idx]
        if isinstance(node, dict):
            if seg not in node:
                raise KeyError(seg)
            return _descend(node[seg], idx + 1)

        if isinstance(node, list):
            digits = seg[1:] if seg.startswith("-") else seg
            if not (digits and digits.isascii() and digits.isdigit()):
                raise ValueError(f"invalid index: {seg}")
            list_idx = int(seg)
            if list_idx < -len(node) or list_idx >= len(node):
                raise IndexError(f"index out of range: {seg}")
            return _descend(node[list_idx], idx + 1)

        raise TypeError(f"cannot descend into {type(node).__name__} at segment {seg!r}")

    return _descend(data, 0)

def top_k_frequent(items, k):
    if not isinstance(items, list):
        raise TypeError("items must be a list")
    if isinstance(k, bool) or not isinstance(k, int):
        raise TypeError("k must be an int")
    if k < 0:
        raise ValueError("k must be >= 0")

    if k == 0 or not items:
        return []

    counts = {}
    for item in items:
        if item in counts:
            counts[item] += 1
        else:
            counts[item] = 1

    pairs = list(counts.items())
    n = len(pairs)
    width = 1
    while width < n:
        for start in range(0, n, 2 * width):
            mid = start + width
            if mid >= n:
                continue
            end = start + 2 * width
            if end > n:
                end = n

            left = pairs[start:mid]
            right = pairs[mid:end]
            i = 0
            j = 0
            dest = start
            len_left = len(left)
            len_right = len(right)

            while i < len_left and j < len_right:
                if left[i][1] >= right[j][1]:
                    pairs[dest] = left[i]
                    i += 1
                else:
                    pairs[dest] = right[j]
                    j += 1
                dest += 1

            while i < len_left:
                pairs[dest] = left[i]
                i += 1
                dest += 1

            while j < len_right:
                pairs[dest] = right[j]
                j += 1
                dest += 1

        width *= 2

    return pairs[:k]
